// Üretilen dosya: tool/ozgun/uret.py. Sanat · Rönesans ve Barok sanatı ayrıntılı (kolay).
const ozArt6Kolay = <(String, String, List<String>, String)>[
  ('Masaccio\'nun Brancacci Şapeli\'ndeki \'Vergi Parası\' freskinde Aziz Petrus aynı resimde üç kez görünür: İsa\'nın yanında, balığın ağzından sikkeyi alırken ve vergiyi öderken. Bu yöntem hangi anlatım biçimine örnektir?', 'Sürekli anlatım', ['Hiyerarşik ölçek', 'Ters perspektif', 'Eşzamanlı kontrast'], 'Sürekli anlatımda bir öykünün farklı anları aynı resim alanında tek bir mekânda gösterilir. Masaccio bu eski yöntemi tutarlı bir perspektif mekânında kullanmıştır.'),
  ('Masaccio 1401\'de doğup 1428\'de Roma\'da öldü. Bu bilgiye göre ressam Rönesans resmini değiştiren eserlerini hangi yaş aralığında yapmıştır?', 'Yirmili yaşlarında', ['Otuzlu yaşlarında', 'Kırklı yaşlarında', 'Ellili yaşlarının başında'], 'Masaccio 27. yaş gününe ulaşmadan ölmüştür. \'Kutsal Üçleme\' ve Brancacci freskleri yirmili yaşlarının ikinci yarısına aittir.'),
  ('1400 dolaylarında Avrupa saraylarında yayılan Uluslararası Gotik üslubu en iyi hangisi tanımlar?', 'Zarif kıvrımlı çizgi, bol altın ve ayrıntılı saray giysileri', ['Sert ışık-gölge karşıtlığı ve sokaktan seçilmiş modeller', 'Tek kaçış noktalı ölçülü mekân ve sade renkler', 'Kalın boya katmanı ve serbest, görünür fırça izi'], 'Uluslararası Gotik süslemeci, aristokrat ve ayrıntıcı bir üsluptur. Mekân ve hacim sorunları yerine zarafet ve görkem öne çıkar.'),
  ('Andrea Mantegna, yaşamının son yaklaşık yarım yüzyılında Mantova\'da hangi hanedanın saray ressamı olarak çalışmıştır?', 'Gonzaga', ['Este', 'Sforza', 'Montefeltro'], 'Mantegna 1460\'ta Ludovico Gonzaga\'nın hizmetine girdi ve 1506\'daki ölümüne dek Mantova sarayında kaldı.'),
  ('Adını doğduğu kentten alan Rönesans ressamı Antonello da Messina hangi adada doğmuştur?', 'Sicilya', ['Sardinya', 'Korsika', 'Girit'], 'Messina, Sicilya\'nın kuzeydoğusundaki liman kentidir. Antonello Napoli\'de Flaman resmini tanımış, sonra Venedik\'te de çalışmıştır.'),
  ('Botticelli\'nin parşömen üzerine yaptığı ve büyük kısmı günümüze ulaşan uzun çizim dizisi hangi edebi eseri resimler?', 'Dante\'nin İlahi Komedya\'sı', ['Petrarca\'nın Şarkılar Kitabı', 'Ovidius\'un Dönüşümler\'i', 'Vergilius\'un Aeneis\'i'], 'Bu çizimler büyük olasılıkla Lorenzo di Pierfrancesco de\' Medici için yapıldı. Cehennem\'in huni biçimli haritası dizinin en tanınan sayfalarındandır.'),
  ('Asıl adı Alessandro Filipepi olan ressamın aldığı \'Botticelli\' lakabı ne anlama gelir?', 'Küçük fıçı', ['Küçük kuş', 'Güzel çizgi', 'Altın el'], 'Lakap, ağabeyine takılan \'Botticello\' (fıçıcık) adından gelir ve aile adıyla birlikte ressama geçmiştir.'),
  ('Vatikan\'daki Sistina Şapeli adını, yapıyı inşa ettiren ve 1480\'lerin başında duvarlarını Botticelli, Perugino ve Ghirlandaio\'ya boyatan hangi papadan alır?', 'IV. Sixtus', ['II. Julius', 'X. Leo', 'V. Sixtus'], 'Şapel 1470\'lerde IV. Sixtus döneminde yapıldı. Michelangelo\'nun tavanı ise yeğeni II. Julius\'un isteğiyle sonradan boyandı.'),
  ('Leonardo da Vinci\'yi 1480\'lerin başında Milano\'ya çağıran ve \'Son Akşam Yemeği\'ni ona yaptıran hükümdar kimdir?', 'Ludovico Sforza', ['Federico da Montefeltro', 'Lorenzo de\' Medici', 'Cesare Borgia'], '\'Il Moro\' lakaplı Ludovico Sforza\'ya yazdığı mektupta Leonardo daha çok askerî mühendislik becerilerini öne çıkarmıştı. Milano\'da yaklaşık on yedi yıl kaldı.'),
  ('Leonardo da Vinci\'nin Mona Lisa\'sı hangi ağaçtan yapılmış bir pano üzerine boyanmıştır?', 'Kavak', ['Meşe', 'Ihlamur', 'Ceviz'], 'İtalyan ressamlar genellikle kavak panolar kullanırdı. Mona Lisa\'nın kavak panosunda zamanla bir çatlak oluştuğu bilinir.'),
  ('Yağlı boyanın yumurta temperasına göre çok daha yavaş kuruması ressama hangi olanağı sağlamıştır?', 'Renkleri yüzeyde yumuşakça harmanlayıp sonradan düzeltebilme', ['Bir günde bitirilmesi gereken sıva bölümleriyle çalışma', 'Altın varağı doğrudan boyanın içine karıştırma', 'Yalnızca ince paralel çizgilerle gölgeleme yapma'], 'Yağlı boya günlerce işlenebilir kalır. Bu sayede ton geçişleri yumuşatılabilir, katmanlar üst üste sürülebilir ve hatalar düzeltilebilir.'),
  ('Bir Rönesans atölyesine giren genç bir çırağın ilk görevleri arasında aşağıdakilerden hangisi yer alırdı?', 'Pigment öğütmek ve panoları astarlamak', ['Sunak resminin ana figürlerini kendi başına boyamak', 'Patronla sözleşme imzalamak', 'Kilise freskinin tasarımını yapmak'], 'Çıraklar yıllarca malzeme hazırlayarak ve ustanın çizimlerini kopyalayarak işi öğrenirdi. Ana figürler genellikle ustaya ya da kıdemli yardımcılara kalırdı.'),
  ('Ghent\'teki \'Kutsal Kuzu\'ya Tapınma\' sunağı gibi ikiden çok sayıda panodan oluşan, menteşeli kanatları olan büyük sunak resimlerine genel olarak ne ad verilir?', 'Poliptik', ['Tondo', 'Diptik', 'Lünet'], 'Diptik iki, triptik üç panodan oluşur; daha fazla panolu sunaklar poliptik adını alır. Ghent Sunağı açık ve kapalı hâlleriyle yirmiye yakın pano içerir.'),
  ('1503-1505 yıllarında Leonardo, Floransa\'daki Palazzo Vecchio\'nun büyük konsey salonu için \'Anghiari Savaşı\'nı hazırlarken, aynı salona \'Cascina Savaşı\'nı tasarlamakla görevlendirilen rakibi kimdir?', 'Michelangelo Buonarroti', ['Raffaello Sanzio', 'Andrea del Sarto', 'Fra Bartolomeo della Porta'], 'İki ustanın aynı salonda yarışması dönemin en ünlü sanat olaylarından biriydi. İkisi de bitmedi; ancak kartonları ve kopyaları genç ressamlar için bir okul işlevi gördü.'),
  ('Leonardo\'nun \'Kayalıkların Meryemi\' tablosunun birbirine çok benzeyen iki versiyonu vardır. Bunlar bugün hangi iki müzededir?', 'Louvre ve Londra Ulusal Galerisi', ['Uffizi ve Prado Müzesi', 'Vatikan Pinakotekası ve Ermitaj', 'Brera Pinakotek\'i ve Viyana Sanat Tarihi Müzesi'], 'Louvre\'daki versiyon daha erkendir. Londra\'daki ikinci versiyon, Milano\'daki bir kardeşlik ile süren ücret anlaşmazlığından sonra tamamlanmıştır.'),
  ('Leonardo, Vinci kasabasında evlilik dışı bir çocuk olarak doğmuştur. Babası Ser Piero\'nun mesleği neydi?', 'Noter', ['Eczacı', 'Yün tüccarı', 'Kuyumcu'], '\'Ser\' unvanı noterlere verilirdi. Babası Leonardo\'yu Floransa\'da Verrocchio\'nun atölyesine çırak olarak yerleştirdi.'),
  ('Mona Lisa\'nın İtalyancada \'La Gioconda\', Fransızcada \'La Joconde\' diye de anılması nereden gelir?', 'Modelin kocası Francesco del Giocondo\'nun soyadından', ['Leonardo\'nun ressam öğrencisi Giocondo\'nun adından', 'İtalyancada \'neşeli kadın\' anlamına gelen bir lakaptan', 'Tabloyu ilk satın alan Fransız soylunun adından'], 'Model Lisa Gherardini, ipek tüccarı Francesco del Giocondo\'nun eşiydi. Ad aynı zamanda \'neşeli\' anlamına gelen giocondo sözcüğüyle de oynar.'),
  ('Michelangelo\'nun \'Son Yargı\'sında, derisi yüzülerek şehit edilmiş Aziz Bartholomeus elinde kendi derisini tutar. Bu sarkık derideki yüzün kime ait olduğu kabul edilir?', 'Ressamın kendi yüzüne', ['II. Julius\'un yüzüne', 'Kutsal Roma imparatorunun yüzüne', 'Raffaello\'nun yüzüne'], 'Çarpık deri yüzü, Michelangelo\'nun buruk bir otoportresi olarak yorumlanır. Sanatçının yaşlılıktaki manevi kaygılarının izi sayılır.'),
  ('Michelangelo\'nun kırk yılı aşkın sürede defalarca küçültülüp değiştirilen ve kendisinin \'mezarın trajedisi\' diye andığı anıt mezar hangi papa için tasarlanmıştı?', 'II. Julius', ['X. Leo', 'VII. Clemens', 'III. Paulus'], 'İlk tasarım kırktan fazla heykelli serbest duran bir yapıydı. Sonunda Roma\'daki San Pietro in Vincoli\'de, ortasında Musa bulunan bir duvar anıtına indirgendi.'),
  ('Vatikan\'daki Pietà, 1972\'de bir ziyaretçinin çekiçli saldırısıyla zarar görüp onarılmıştır. Bu olaydan sonra eser nasıl sergilenmeye başlanmıştır?', 'Kurşun geçirmez bir camın arkasında', ['Kopyasıyla değiştirilip aslı depoya kaldırılarak', 'Yalnız randevulu küçük gruplara açılarak', 'Bazilikadan alınıp Vatikan Müzeleri\'ne taşınarak'], 'Saldırıda Meryem\'in kolu, burnu ve göz kapağı kırıldı. Restorasyondan sonra heykel aynı yerde, koruyucu camın ardında sergilenmektedir.'),
  ('1564\'te Roma\'da ölen Michelangelo\'nun cenazesi gizlice Floransa\'ya götürülmüştür. Sanatçı bugün nerede gömülüdür?', 'Floransa\'daki Santa Croce Kilisesi\'nde', ['Roma\'daki Aziz Petrus Bazilikası\'nda', 'Roma\'daki Pantheon\'da', 'Floransa\'daki San Lorenzo Kilisesi\'nin Medici Şapeli\'nde'], 'Floransalılar, ustanın kendi kentinde yatmasını istedikleri için cenazeyi bir yük gibi gizleyerek taşıdı. Mezar anıtını Vasari tasarlamıştır.'),
  ('1504\'te Floransa\'da Leonardo ve Botticelli gibi sanatçıların da katıldığı bir kurul, Michelangelo\'nun Davut\'unun nereye konacağını tartıştı. Heykel sonunda nereye yerleştirildi?', 'Palazzo Vecchio\'nun girişinin önüne', ['Katedralin kuzey payandasının tepesine', 'Medici Sarayı\'nın avlusuna', 'Vaftizhanenin doğu kapılarının karşısına'], 'Heykel, kent yönetiminin sarayının önünde cumhuriyetin simgesi olarak durdu. 1873\'te korunmak için Akademi Galerisi\'ne taşındı, yerine bir kopya konuldu.'),
  ('\'Atina Okulu\'nun ön planında bir mermer bloğa dayanıp yazı yazan, çizme giymiş düşünceli Herakleitos figürüne kimin yüz hatlarının verildiği düşünülür?', 'Michelangelo', ['Donato Bramante', 'Raffaello\'nun kendisi', 'Papa II. Julius'], 'Bu figür freskin ilk tasarımında yoktu; Raffaello onu Sistina tavanının ilk bölümünü gördükten sonra eklediği düşünülür. Kalın ve heykelsi biçimi Michelangelo üslubuna bir saygı sayılır.'),
  ('Yalnız birkaç eseri kesin olarak kendisine atfedilen Giorgione, 1510\'da otuzlu yaşlarının başında Venedik\'te neden ölmüştür?', 'Veba salgını yüzünden', ['Bir düelloda aldığı yaradan', 'Kanalda boğularak', 'Engizisyon zindanında'], 'Giorgione\'nin erken ölümü, eserlerinin atıf sorununu da büyütmüştür. Bazı tablolarını Tiziano ya da Sebastiano del Piombo\'nun tamamladığı düşünülür.'),
  ('Tiziano\'nun Prado\'daki ünlü atlı portresi, 1547\'de Protestan prenslere karşı kazandığı savaştan sonra zırhı içinde atının üstünde bir hükümdarı gösterir. Bu hükümdar kimdir?', 'V. Karl', ['II. Felipe', 'I. François', 'VIII. Henry'], '\'Mühlberg\'deki V. Karl\', Avrupa saray atlı portresinin temel örneklerinden biri oldu. Tiziano, imparatorun en gözde ressamıydı.'),
  ('Asıl adı Jacopo Robusti olan Tintoretto, \'küçük boyacı\' anlamına gelen lakabını babasının hangi mesleğinden almıştır?', 'Kumaş boyacılığı', ['Kuyumculuk', 'Ev ve duvar boyacılığı', 'Cam ustalığı'], 'İtalyancada \'tintore\' kumaş boyacısı demektir. Lakap, ressamın babasının işinden türeyen bir küçültme adıdır.'),
  ('Kaynaklara göre Tintoretto, kalabalık kompozisyonlarında ışık ve gölge düzenini önceden denemek için nasıl bir yöntem kullanmıştır?', 'Küçük balmumu figürlerini ışıklı kutular içinde düzenlemek', ['Canlı modelleri kilise içinde gerçek boyutta sahne gibi dizip gözlemlemek', 'Camera obscura ile Venedik sokaklarını kopyalamak', 'Önceki tabloların baskılarını kesip yapıştırmak'], 'Bu maket yöntemi, dramatik ve beklenmedik bakış açıları ile ışık kaynaklarını kurmasına yardım etti. Ridolfi bu alışkanlığı ayrıntılı biçimde anlatır.'),
  ('Louvre\'un en büyük tablosu olan ve 1797\'de Napolyon\'un askerlerince Venedik\'teki San Giorgio Maggiore manastırının yemekhanesinden götürülen Veronese tablosu hangisidir?', 'Kana\'daki Düğün', ['Levi\'nin Evinde Şölen', 'Darius\'un Ailesi İskender\'in Önünde', 'Emmaus\'taki Akşam Yemeği'], 'Tablo bugün Louvre\'da Mona Lisa\'nın karşısındaki duvarda asılıdır. İsa\'nın suyu şaraba çevirdiği düğün, Venedik giysileri içinde görkemli bir şölene dönüşmüştür.'),
  ('Asıl adı Paolo Caliari olan ressam \'Veronese\' lakabını nereden almıştır?', 'Doğduğu kent Verona\'dan', ['Babasının taş ustası olarak çalıştığı ocaktan', 'Venedik\'te oturduğu mahalleden', 'Hocasının soyadından'], 'Veronese 1528\'de Verona\'da doğmuş, sonra Venedik\'e yerleşmiştir. Lakap, Venedik\'te onu kökeniyle ayırt etmek için kullanılmıştır.'),
  ('Venedik\'teki Harry\'s Bar\'da 20. yüzyılda ortaya çıkan ince dilimlenmiş çiğ et yemeğine, kırmızı tonları tablolarını çağrıştırdığı için adı verilen Venedikli Rönesans ressamı kimdir?', 'Vittore Carpaccio', ['Giovanni Bellini', 'Lorenzo Lotto', 'Cima da Conegliano'], 'Carpaccio, Azize Ursula\'nın yaşamını anlatan tablo dizisi gibi anlatı resimleriyle tanınır. Yemeğin adı, ressamın tablolarındaki parlak kırmızılara bir göndermedir.'),
  ('Correggio\'nun Dresden\'deki \'Kutsal Gece\' tablosunda sahneyi aydınlatan ışık nereden gelir?', 'Yeni doğmuş İsa\'nın bedeninden', ['Ahırın çatısındaki kandilden', 'Gökyüzündeki Beytüllahim yıldızından', 'Çobanların taşıdığı meşalelerden'], 'Çocuktan yayılan ışık çevredeki yüzleri aydınlatır ve bir çobanın gözlerini kamaştırır. Bu çözüm, Barok gece sahnelerine örnek olmuştur.'),
  ('Hieronymus Bosch\'un tablolarının büyük bölümünün bugün Madrid\'deki Prado Müzesi\'nde bulunmasının başlıca nedeni nedir?', 'İspanya Kralı II. Felipe\'nin tutkulu bir Bosch koleksiyoncusu olması', ['Napolyon\'un eserleri Hollanda\'dan İspanya\'ya taşıması', 'Bosch\'un son yıllarını Madrid\'de İspanyol kraliyet sarayında çalışarak geçirmesi', 'Prado\'nun 20. yüzyılda eserleri açık artırmayla toplaması'], 'II. Felipe, Bosch tablolarını Escorial Sarayı için toplattı. Habsburg mirası, eserlerin İspanya\'da kalmasını sağladı.'),
  ('Bir iskelet ordusunun yaşlı-genç, kral-köylü ayırt etmeden canlıları kuşattığı, Prado\'daki panoramik Pieter Bruegel tablosu hangisidir?', 'Ölümün Zaferi', ['Asi Meleklerin Düşüşü', 'Deli Griet', 'Karnaval ile Perhiz\'in Savaşı'], 'Tablo, Orta Çağ\'ın \'ölüm dansı\' geleneğini acımasız bir savaş sahnesine dönüştürür. Ölüm karşısında herkesin eşitliğini vurgular.'),
  ('Viyana\'daki Albertina Müzesi\'nde bulunan, her bir tüyü ayrı ayrı işlenmiş 1502 tarihli suluboya ve guaş \'Genç Tavşan\' kimin eseridir?', 'Albrecht Dürer', ['Hans Holbein', 'Lucas Cranach', 'Albrecht Altdorfer'], 'Dürer doğayı titiz bir gözlemle inceleyen çalışmalar yaptı. Gözdeki pencere yansıması, çalışmanın kapalı bir odada yapıldığını düşündürür.'),
  ('Hans Holbein\'in birkaç kez profilden, masada yazı yazarken resmettiği ve onun İngiltere\'ye gitmesine aracı olan Hollandalı hümanist kimdir?', 'Rotterdamlı Erasmus', ['Martin Luther', 'Thomas More', 'Philipp Melanchthon'], 'Erasmus, Holbein\'i Londra\'daki dostu Thomas More\'a tanıştırdı. Holbein böylece İngiltere\'de çalışma olanağı buldu.'),
  ('Albrecht Altdorfer\'in on binlerce askeri kuşbakışı ve kıvrılan dev bir gökyüzü altında gösteren 1529 tarihli tablosu hangi savaşı gösterir?', 'İskender\'in İssos Savaşı', ['Mohaç Savaşı', 'Pavia Savaşı (1525) ve I. François\'nın esir düşüşü', 'Viyana Kuşatması'], 'Bavyera Dükü IV. Wilhelm için yapılan tablo bugün Münih\'tedir. Napolyon tabloyu öyle beğenmişti ki Saint-Cloud\'daki banyosuna astırdığı anlatılır.'),
  ('Rönesans Müjde sahnelerinde meleğin elinde ya da odadaki bir vazoda sıkça görülen beyaz zambak neyi simgeler?', 'Meryem\'in saflığını', ['Kral Davut soyunu', 'Yaklaşan baharı', 'Floransa kentinin gücünü'], 'Beyaz zambak geleneksel olarak lekesizlik ve bekâretin simgesidir. Floransa\'nın arma zambağı ise kırmızıdır ve farklı bir anlam taşır.'),
  ('Bir müzedeki Rönesans tablosunda, kitaplarla dolu bir çalışma odasında oturan yaşlı bir bilgin, ayağının dibinde yatan bir aslan ve duvarda asılı kırmızı bir kardinal şapkası görülüyor. Betimlenen aziz büyük olasılıkla kimdir?', 'Aziz Hieronymus', ['Aziz Markos', 'Aziz Augustinus', 'Aziz Ambrosius'], 'Efsaneye göre Hieronymus bir aslanın pençesinden diken çıkarmış, aslan da ona sadık kalmıştır. İncil\'i Latinceye çevirdiği için kitaplarla, kilise içindeki yüksek konumu için de kardinal şapkasıyla gösterilir.'),
  ('Çıplak bedenine saplanmış oklarla bir direğe ya da ağaca bağlı gösterilen ve veba salgınlarında koruyucu olarak yakarılan aziz kimdir?', 'Aziz Sebastianus', ['Aziz Laurentius', 'Aziz Stefanos', 'Aziz Rochus'], 'Romalı subay Sebastianus okla öldürülmek istenmiş ama kurtulmuştur. Oklar vebanın ani darbelerine benzetildiği için veba azizi sayılır; Rönesans\'ta çıplak beden çalışmaları için de sevilen bir konuydu.'),
  ('Venedik Cumhuriyeti\'nin simgesi olan kanatlı aslan, dört İncil yazarından hangisinin geleneksel simgesidir?', 'Markos', ['Matta', 'Luka', 'Yuhanna'], 'Aziz Markos\'un kalıntılarının 828\'de İskenderiye\'den Venedik\'e getirildiğine inanılır. Kanatlı aslan böylece kentin bayraklarına ve yapılarına yerleşti.'),
  ('Bir Rönesans tablosunda deve kılından kaba bir giysi giymiş, elinde ince kamıştan bir haç tutan ve yanında bir kuzu bulunan sakallı bir aziz görülüyor. Bu figür kimdir?', 'Vaftizci Yahya', ['Aziz Yusuf', 'Aziz Petrus', 'Aziz Hieronymus'], 'Yahya çölde deve kılından giysiyle yaşamıştır. Kuzu, onun İsa için söylediği \'İşte Tanrı\'nın kuzusu\' sözüne gönderme yapar.'),
  ('Elinde bir merhem kavanozu tutan, uzun ve dağınık saçlarıyla tanınan azize kimdir?', 'Mecdelli Meryem', ['Bakire Meryem', 'Azize Anna', 'Azize Marta'], 'Kavanoz, İsa\'nın ayaklarını kokulu yağla yıkadığı ve mezara yağ götürdüğü anlatılarına gönderme yapar. Uzun saçlar tövbe edişini çağrıştırır.'),
  ('Sırtında küçük bir çocuğu taşıyarak bir nehri geçiren, elinde ağaç gövdesinden bir değnek bulunan iri yapılı aziz kimdir?', 'Aziz Kristoforos', ['Aziz Yorgi', 'Aziz Martinus', 'Aziz Nikolaos'], 'Adı \'İsa\'yı taşıyan\' anlamına gelir. Efsaneye göre taşıdığı çocuk giderek ağırlaşmış ve dünyayı taşıyan İsa olduğu anlaşılmıştır; yolcuların koruyucusu sayılır.'),
  ('Dirilen İsa\'nın bahçede onu bahçıvan sanan Mecdelli Meryem\'e \'Bana dokunma\' dediği sahne, Rönesans resminde hangi Latince adla anılır?', 'Noli me tangere', ['Ecce Homo', 'Quo vadis', 'Salvator Mundi'], 'Sahne Yuhanna İncili\'ne dayanır. Tiziano ve Correggio gibi ressamlar konuyu bahçe manzarası içinde iki figürün jestleriyle işlemiştir.'),
  ('Pilatus\'un kırbaçlanmış ve dikenli taç takılmış İsa\'yı halka gösterdiği sahneye resim sanatında hangi Latince ad verilir?', 'Ecce Homo', ['Noli me tangere', 'Agnus Dei', 'Pax vobiscum'], '\'İşte adam\' anlamına gelen söz Yuhanna İncili\'nde Pilatus\'a aittir. Sahne çoğu zaman İsa\'nın tek başına, morarmış ve alaycı bir pelerinle gösterildiği yakın planlara dönüşmüştür.'),
  ('Tiziano, Rembrandt ve Orazio Gentileschi\'nin de resmettiği bir mitolojide, Zeus kulede kapatılmış bir prensesi altın yağmuru biçiminde ziyaret eder. Bu prenses kimdir?', 'Danae', ['Leda', 'Europa', 'İo'], 'Danae\'nin bu birleşmeden Perseus doğmuştur. Altın yağmuru Rönesans\'ta hem tanrısal ışık hem de parayla satın alınan aşk olarak yorumlanmıştır.'),
  ('Rubens\'in de birçok kez resmettiği mitolojik güzellik yarışmasında çoban Paris altın elmayı hangi tanrıçaya verir?', 'Venüs (Afrodit)', ['Juno (Hera)', 'Minerva (Athena)', 'Diana (Artemis)'], 'Venüs, Paris\'e dünyanın en güzel kadını Helena\'yı vaat etmişti. Bu seçim Truva Savaşı\'nın başlangıcı sayılır.'),
  ('Avcı Aktaion, ormanda yıkanan Diana\'yı ve perilerini rastlantıyla görür. Tiziano\'nun da II. Felipe için resmettiği bu mitolojide Aktaion\'un başına ne gelir?', 'Geyiğe dönüştürülüp kendi köpeklerince parçalanır', ['Taşa dönüştürülüp yıkandığı pınarın başında kalır', 'Kör edilip ömür boyu ormanda dolaşmaya mahkûm edilir', 'Diana tarafından takımyıldız olarak göğe yerleştirilir'], 'Ceza, tanrısal olanın yasak bakışa karşı acımasızlığını anlatır. Tiziano öykünün iki anını ayrı tablolarda resmetmiştir.'),
  ('Orta Çağ ve Rönesans simgeciliğinde göğsünü gagalayıp yavrularını kendi kanıyla beslediğine inanılan kuş neyi simgeler?', 'İsa\'nın insanlık için kendini feda edişini', ['Bilgeliği ve uzun ömrü', 'Bereketi ve evlilik sadakatini', 'Kibri ve dünyevi gösterişi'], 'Pelikan efsanesi, kutsal ayindeki kan ve kurtuluş fikriyle ilişkilendirildi. Kuş, sunak resimlerinde ve haçların tepesinde sıkça görülür.'),
  ('Meryem ve Çocuk İsa tablolarında İsa\'nın elinde ya da yakınında sıkça görülen saka kuşu neyi önceden haber verir?', 'İsa\'nın çarmıhtaki acısını', ['Meryem\'in göğe yükselişini', 'Müneccimlerin gelişini', 'Baharın ve bereketin dönüşünü'], 'Efsaneye göre saka kuşu İsa\'nın başındaki dikenli taçtan bir diken çekerken kanla lekelenmiştir. Kırmızı yüz lekesi bu öyküyle açıklanır.'),
  ('Caravaggio\'nun Roma\'daki Borghese Galerisi\'nde bulunan \'Golyat\'ın Başını Tutan Davut\' tablosunda kesik Golyat başına kimin yüz hatlarının verildiği kabul edilir?', 'Caravaggio\'nun kendisinin', ['Papa V. Paulus\'un', 'Ranuccio Tomassoni\'nin', 'Kardinal Scipione Borghese\'nin'], 'Tablo, cinayetten sonra af dilenen Caravaggio\'nun kendini kesik baş olarak sunduğu bir pişmanlık işareti diye yorumlanır.'),
  ('Asıl adı Michelangelo Merisi olan ressam \'Caravaggio\' adıyla anılır. Bu ad nereden gelir?', 'Ailesinin geldiği Lombardiya\'daki kasabadan', ['Roma\'da yaşadığı mahallenin adından', 'Babasının taşıdığı soylu unvandan', 'Hocasının atölyesinin bulunduğu sokaktan'], 'Caravaggio, Milano yakınlarındaki küçük bir kasabadır. Ressam bu adla tanınarak aynı adı taşıyan Michelangelo Buonarroti\'den de ayırt edildi.'),
  ('Bolonya okulundan Giovanni Francesco Barbieri\'nin \'Guercino\' lakabı neye dayanır?', 'Şaşılığına', ['Kısa boyuna', 'Kekemeliğine', 'Solaklığına'], 'İtalyanca \'guercio\' şaşı ya da tek gözü bozuk demektir. Guercino\'nun Roma\'daki Casino Ludovisi\'de yaptığı \'Aurora\' tavanı Reni\'ninkiyle sık karşılaştırılır.'),
  ('Bernini\'nin 1665\'te Paris\'e yaptığı tek yolculukta, saçları ve pelerini rüzgârda savruluyormuş gibi gösterdiği mermer büstü kimi tasvir eder?', 'XIV. Louis\'yi', ['XIII. Louis\'yi', 'Kardinal Mazarin\'i', 'Jean-Baptiste Colbert\'i'], 'Büst bugün Versailles\'dadır. Bernini, aynı yolculukta Louvre\'un doğu cephesi için de projeler hazırlamış, ancak bunlar uygulanmamıştır.'),
  ('Velázquez\'in \'Nedimeler\' tablosunda, nedimelerin ve saray cücelerinin arasında merkezde duran beyaz giysili küçük prenses kimdir?', 'Infanta Margarita Teresa', ['Infanta María Teresa', 'Kraliçe Mariana', 'Infanta Isabel Clara Eugenia'], 'Margarita Teresa, IV. Felipe ile Avusturyalı Mariana\'nın kızıydı. Velázquez onu çocukluğu boyunca birkaç kez resmetmiştir; sonradan İmparator I. Leopold\'le evlendi.'),
  ('Zurbarán\'ın koyu bir zemin önünde ayakları bağlanmış, bir masa üzerinde yatan tek bir kuzuyu gösteren \'Agnus Dei\' tablosu neyi simgeler?', 'İsa\'nın kurban edilişini', ['Kırsal yaşamın bolluğunu', 'Bir çobanın sadakatini', 'Paskalya sofrasının zenginliğini'], '\'Tanrı\'nın Kuzusu\' İsa\'nın bir unvanıdır. Hayvanın sessiz teslimiyeti, çarmıhtaki fedakârlığa işaret eder.'),
  ('Girit\'te ikona ressamı olarak yetişen El Greco, İspanya\'ya gelmeden önce hangi İtalyan kentinde bulunmuş ve Tiziano\'nun çevresinde rengi kullanmayı öğrenmiştir?', 'Venedik', ['Floransa', 'Napoli', 'Cenova'], 'Girit o dönemde Venedik yönetimindeydi. El Greco daha sonra Roma\'ya geçti ve 1577\'de Toledo\'ya yerleşti.'),
  ('Asıl adı Domenikos Theotokopoulos olan El Greco tablolarının çoğunu hangi alfabeyle imzalamıştır?', 'Yunan alfabesiyle', ['Latin alfabesiyle', 'Kiril alfabesiyle', 'Ermeni alfabesiyle'], 'El Greco, İspanya\'da yaşadığı otuz yılı aşkın süre boyunca Yunan kimliğini imzasında korumuştur. Lakabı da İtalyanca ve İspanyolca karışımı \'Yunanlı\' demektir.'),
  ('Anvers Katedrali\'nde \'Haçın Kaldırılışı\'nın karşı tarafında yer alan, İsa\'nın bedeninin beyaz bir örtü üzerinden aşağı kaydığı Rubens triptiği hangisidir?', 'Çarmıhtan İndiriliş', ['Ölü İsa\'ya Ağıt', 'Meryem\'in Göğe Yükselişi', 'Müneccimlerin Tapınması'], 'Triptik, Anvers\'teki arkebüzcüler loncası için yapıldı. Rubens, beyaz örtünün köşegeni boyunca bütün figürlerin ağırlığı taşıdığı akıcı bir hareket kurdu.'),
  ('Rubens\'in Anvers\'teki atölyesinde büyük tabloların çoğu nasıl bir iş bölümüyle üretilirdi?', 'Ustanın küçük taslağına göre yardımcılar boyar, Rubens son dokunuşları yapardı', ['Rubens her tabloyu baştan sona tek başına boyar, yardımcılar yalnızca çerçeve yapardı', 'Yardımcılar konuyu seçer, Rubens yalnızca imza atardı', 'Tablolar ayrı loncalarda parça parça boyanıp sonra birleştirilirdi'], 'Fiyatlar, Rubens\'in kendi elinin payına göre değişirdi. Van Dyck gibi yetenekli yardımcılar ve hayvan ya da manzara uzmanları da atölyede çalışırdı.'),
  ('Bıyıkla birlikte çeneyi sivri bir biçimde çevreleyen kısa sakal tipi, portrelerinde bu modayı sıkça gösteren hangi ressamın adıyla anılır?', 'Van Dyck', ['Rembrandt', 'Velázquez', 'Rubens'], 'I. Charles ve saray çevresinin taşıdığı bu sakal, \'Van Dyck sakalı\' olarak adlandırılır. Ressam kendisini de bu sakalla resmetmiştir.'),
  ('Anthony van Dyck gençlik yıllarında hangi ustanın atölyesinde en önemli yardımcı olarak çalışmıştır?', 'Peter Paul Rubens', ['Jacob Jordaens', 'Frans Snyders', 'David Teniers'], 'Rubens, van Dyck\'i \'en iyi öğrencim\' diye anardı. Van Dyck daha sonra kendine özgü zarif ve ince portre üslubunu geliştirdi.'),
  ('Jacob Jordaens\'in \'Kral İçiyor\' adlı kalabalık şölen tablolarında konu edilen gelenek nedir?', 'Müneccimler Yortusu\'nda pastadan fasulye çıkanın o akşamın kralı seçilmesi', ['Yeni seçilen belediye başkanının loncalarca kutlanması', 'Bir kral ziyareti sonrasında kentte verilen resmî ziyafet', 'Hasat sonunda köyün en yaşlısının onurlandırılması'], '6 Ocak\'taki şölende fasulyeyi bulan kişi taç takar, o kadeh kaldırınca herkes \'Kral içiyor!\' diye bağırırdı. Jordaens bu neşeli kargaşayı birçok kez resmetti.'),
  ('Jacob Jordaens\'in yaşlıların şarkı söylediği, çocukların ise flüt çaldığı ünlü tablosu hangi düşünceyi işler?', 'Çocukların büyüklerinin davranışını örnek aldığını', ['Gençliğin yaşlılıktan daha mutlu olduğunu', 'Müziğin kuşaklar arasındaki kavgaları bitirdiğini', 'Yoksulların zenginlerden daha neşeli olduğunu'], 'Tablo bir Flaman atasözüne dayanır: \'Yaşlılar nasıl şarkı söylerse gençler öyle çalar.\' Eğitimde örnek olmanın önemini vurgular.'),
  ('Rembrandt\'ın 1656\'da borçları nedeniyle iflas başvurusunda bulunmasının ardından ne olmuştur?', 'Büyük evi ve sanat koleksiyonu açık artırmayla satılmıştır', ['Amsterdam\'dan sürülüp Leiden\'e dönmek zorunda kalmıştır', 'Ressamlar loncasından atılıp resim yapması yasaklanmıştır', 'Kent yönetimi bütün borçlarını üstlenip ona maaş bağlamıştır'], 'Jodenbreestraat\'taki evi ve antika, baskı, silah gibi nesnelerden oluşan koleksiyonu satıldı. Ev bugün Rembrandthuis müzesidir.'),
  ('Georges de La Tour\'un birkaç kez resmettiği bir konuda, genç bir kadın kucağında bir kafatası tutarak bir mum alevine dalgın dalgın bakar. Bu figür kimdir?', 'Tövbekâr Mecdelli Meryem', ['İskenderiyeli Azize Katerina', 'Azize Teresa', 'Bakire Meryem'], 'Kafatası ölümün, mum ise geçici dünyevi yaşamın ve iç aydınlanmanın simgesidir. La Tour bu konuyu sessiz bir tefekkür sahnesi olarak işler.'),
  ('XIV. Louis\'nin baş ressamı olarak Versailles\'daki Aynalı Galeri\'nin tavan resimlerini yapan, Gobelins kraliyet atölyelerini ve Resim Akademisi\'ni yöneten sanatçı kimdir?', 'Charles Le Brun', ['Nicolas Poussin', 'Simon Vouet', 'Pierre Mignard'], 'Le Brun, sarayın bütün görsel programını denetleyen güçlü bir yöneticiydi. Aynalı Galeri tavanı, kralın savaşlarını ve yönetimini alegorilerle anlatır.'),
  ('18. yüzyıl gezginlerinin manzarayı Claude Lorrain\'in tablolarına benzetmek için sırtlarını dönüp baktıkları, koyu renk camlı küçük dışbükey aynaya ne ad verilir?', 'Claude aynası', ['Venedik aynası', 'Kara oda', 'Lorrain merceği'], 'Ayna manzarayı küçültüp tonlarını yumuşatarak bir tabloya dönüştürüyordu. \'Pitoresk\' manzara zevkinin yaygınlaşmasında önemli bir araçtı.'),
  ('Watteau\'nun Louvre\'daki büyük tablosunda, beyaz giysiler içinde kolları iki yanında hareketsiz duran ve izleyiciye bakan palyaço figürü hangi tiyatro geleneğinden gelir?', 'Commedia dell\'arte', ['Antik Yunan tragedyası', 'Japon Kabuki tiyatrosu', 'Orta Çağ mucize oyunları'], 'Pierrot (eski adıyla Gilles), İtalyan doğaçlama komedisinin saf ve hüzünlü tipidir. Watteau bu karakterlerin dünyasını şiirsel bir melankoliyle resmetti.'),
  ('\'Rokoko\' adının kökeni olan Fransızca \'rocaille\' sözcüğü başlangıçta neyi anlatıyordu?', 'Bahçe mağaralarındaki kabuk ve taş süslemelerini', ['Saray balolarında giyilen kabarık etekleri', 'Çin\'den gelen ince porselen kapları', 'Kilise kubbelerindeki altın varaklı ışınları'], 'Deniz kabuklarını ve kaya oyuklarını taklit eden asimetrik kıvrımlar, bu üslubun süsleme dilinin temeli oldu. Ad başlangıçta alaycı bir anlam da taşıyordu.'),
  ('II. Dünya Savaşı\'nda yıkılan Varşova\'nın tarihî merkezinin yeniden yapılmasında, 18. yüzyılda yapılmış ayrıntılı kent manzaraları belge olarak kullanılmıştır. Bu tabloları yapan ressam kimdir?', 'Bernardo Bellotto', ['Francesco Guardi', 'Giovanni Paolo Panini', 'Marco Ricci'], 'Canaletto\'nun yeğeni Bellotto, son yıllarını Polonya kralının saray ressamı olarak Varşova\'da geçirdi. Titiz görünümleri mimarlara yol gösterdi.'),
  ('Giambattista Tiepolo yaşamının son yıllarında kraliyet sarayının tavanlarını boyamak üzere hangi kente gitmiş ve orada ölmüştür?', 'Madrid', ['Viyana', 'Sankt Peterburg', 'Würzburg'], 'Tiepolo 1762\'de III. Carlos\'un daveti üzerine İspanya\'ya gitti ve 1770\'te Madrid\'de öldü. Bu sırada Neoklasik ressam Mengs\'in yükselişiyle gözden düşmeye başlamıştı.'),
  ('Bir müze kataloğunda \'Cinquecento Venedik resmi\' başlıklı bir bölüm var. Bu bölümde aşağıdaki ressamlardan hangisinin eserinin yer alması beklenir?', 'Tiziano', ['Giotto', 'Canaletto', 'Masaccio'], 'Cinquecento 1500\'lü yıllardır ve Tiziano bu yüzyılın Venedikli büyük ustasıdır. Giotto 14., Masaccio 15., Canaletto 18. yüzyıl ressamıdır.'),
  ('İtalyanca \'Seicento\' terimi 1600\'lü yılları anlatır. Aşağıdaki sanatçılardan hangisi bir Seicento sanatçısı olarak nitelendirilebilir?', 'Gian Lorenzo Bernini', ['Sandro Botticelli', 'Giovanni Battista Tiepolo', 'Andrea Mantegna'], 'Bernini\'nin başlıca eserleri 17. yüzyıla aittir. Botticelli ve Mantegna 15. yüzyıl, Tiepolo ise 18. yüzyıl sanatçısıdır.'),
  ('Bir eserde altın zemin yoktur; mekân tek kaçış noktalı perspektifle derinleşir, figürler klasik oranlıdır ve sakin bir piramit kompozisyon içinde dengeli biçimde toplanmıştır. Bu tablo en çok hangi döneme uyar?', 'Yüksek Rönesans', ['Barok', 'Rokoko', 'Uluslararası Gotik'], 'Denge, açıklık ve ideal oran Yüksek Rönesans\'ın belirgin özellikleridir. Barok hareket ve dramatik ışık, Rokoko hafiflik, Uluslararası Gotik ise altın ve süsleme öne çıkarır.'),
  ('Küçük bir meşe pano üzerine yağlı boyayla yapılmış bir eserde, sıradan bir oda içinde Meryem gösterilir; havlu, ibrik ve zambak gibi gündelik nesneler gizli dinsel anlamlar taşır, yüzeyler mücevher gibi parlar. Bu tablo en çok hangi geleneğe aittir?', 'Erken Hollanda resmi', ['Floransa maniyerizmi', 'İspanyol Barok\'u', 'Venedik Rokoko\'su'], '15. yüzyılın Flaman ustaları yağlı boyanın olanaklarını ince ayrıntı ve simgesel gündelik nesnelerle birleştirdi. Meşe pano da Kuzey\'in tipik malzemesidir.'),
  ('Küçük boyutlu bir tuvalde, bir evin sade odasında pencere ışığında mektup okuyan bir kadın gösterilir. Tablo bir kilise için değil, açık piyasada bir burjuva alıcıya satılmak üzere yapılmıştır. Bu eser en olası hangi ortamda üretilmiştir?', '17. yüzyıl Hollanda Cumhuriyeti', ['15. yüzyıl Floransa\'sı', '18. yüzyıl Versailles sarayı', '16. yüzyıl Roma\'sındaki papalık sarayı'], 'Hollanda Altın Çağı\'nda ressamlar ısmarlama yerine çoğunlukla piyasa için küçük tür resimleri üretti. Ev içi sahneleri bu pazarın en sevilen konularındandı.'),
  ('Rönesans heykellerinde figürün ağırlığını tek bacağına verip omuzlarla kalçanın ters yönlere eğilmesi biçimindeki duruş heykele ne kazandırır?', 'Durağan bir figüre doğal bir canlılık ve denge', ['Figüre Bizans ikonalarındaki gibi kesin bir cephesellik', 'Heykelin yalnız tek bir açıdan izlenebilmesi', 'Figürün kaskatı ve törensel bir sessizliğe bürünmesi'], 'Antik Yunan\'dan alınan bu duruş (kontrapost), gövdeye hafif bir S eğrisi verir. Donatello ve Michelangelo\'nun Davut\'ları bunun ünlü örnekleridir.'),
  ('Aşağıdaki ressamlar doğum yıllarına göre eskiden yeniye sıralanırsa hangisi ikinci sırada yer alır?', 'Leonardo da Vinci', ['Masaccio', 'Johannes Vermeer', 'Michelangelo Merisi da Caravaggio'], 'Masaccio 1401, Leonardo 1452, Caravaggio 1571, Vermeer 1632 doğumludur. Sıralamada Leonardo ikinci olur.'),
  ('Aşağıdaki eserlerden hangisi en geç tamamlanmıştır?', 'Rembrandt\'ın Gece Devriyesi', ['Ghent Sunağı', 'Leonardo\'nun Son Akşam Yemeği', 'Sistina Şapeli tavanı'], 'Ghent Sunağı 1432\'de, Son Akşam Yemeği 1498 dolayında, Sistina tavanı 1512\'de, Gece Devriyesi ise 1642\'de tamamlandı.'),
  ('Michelangelo 1475\'te doğmuştur. Sistina Şapeli tavanını 1512\'de bitirdiğinde kaç yaşındaydı?', '37', ['33', '41', '45'], '1512 - 1475 = 37. Yani dev tavanı otuzlu yaşlarının ikinci yarısında tamamlamıştır.'),
  ('Leonardo da Vinci 1452\'de doğmuştur. Mona Lisa\'ya 1503 dolaylarında başladığında yaklaşık kaç yaşındaydı?', '51', ['41', '46', '61'], '1503 - 1452 = 51. Leonardo tablo üzerinde ölümüne dek yıllarca çalışmayı sürdürdü.'),
  ('Bir ressam ufuk çizgisini tuvalin alt kenarına çok yakın çiziyor ve figürleri bu çizginin çok üstüne yükseltiyor. İzleyici sahneye nasıl bakıyormuş gibi hisseder?', 'Aşağıdan yukarıya, figürler üzerine yükseliyormuş gibi', ['Yukarıdan aşağıya, kuşbakışı', 'Yandan, profil olarak', 'Tam göz hizasından, karşıdan ve dümdüz bir bakışla'], 'Ufuk çizgisi izleyicinin göz hizasıdır. Göz hizası düşükse izleyici alçakta durur ve figürler anıtsal görünür; Mantegna bu etkiyi sık kullanmıştır.'),
  ('Bir sunak resminin alt köşelerinde, dönemin modasına uygun giysiler içinde diz çökmüş, ellerini kavuşturmuş küçük figürler görülüyor. Bu figürler büyük olasılıkla kimlerdir?', 'Eseri ısmarlayan bağışçılar', ['İncil\'deki havariler', 'Ressamın çırakları', 'Kilisenin koruyucu melekleri'], 'Bağışçılar kendilerini kutsal sahnenin yanında dua ederken resmettirerek hem dindarlıklarını hem de toplumsal konumlarını gösterirdi.'),
  ('17. yüzyıl Hollanda tablolarında sabun köpüğü üfleyen bir çocuk motifi genellikle neyi simgeler?', 'Yaşamın geçici ve kırılgan olduğunu', ['Temizliğin ahlaki erdemini', 'Çocukluğun sonsuz neşesini ve oyun özgürlüğünü', 'Bilimsel deneylere duyulan merakı'], 'Latince \'homo bulla\' (insan bir köpüktür) deyişine dayanan motif, vanitas düşüncesinin bir parçasıdır. Köpük gibi yaşam da her an sönebilir.'),
  ('Rembrandt 1606\'da doğmuştur. \'Gece Devriyesi\'ni 1642\'de tamamladığında kaç yaşındaydı?', '36', ['32', '42', '46'], '1642 - 1606 = 36. Aynı yıl karısı Saskia da ölmüştür.'),
  ('Raffaello 1483\'te doğmuş, \'Atina Okulu\'nu 1511 dolaylarında bitirmiştir. Bu ünlü freski bitirdiğinde yaşı kaç civarındaydı?', '28', ['23', '33', '37'], '1511 - 1483 = 28. Raffaello Roma\'ya geldiğinde yirmi beş yaşındaydı ve kısa sürede papanın gözde ressamı oldu.'),
  ('Doğrusal perspektifle çizilen bir sütun dizisinde, gerçekte eşit aralıklarla dizilmiş sütunlar kaçış noktasına doğru nasıl görünür?', 'Giderek kısalır ve aralarındaki boşluklar daralır', ['Hep aynı boyda kalır ama aralarındaki boşluklar giderek açılır', 'Giderek uzar ve kalınlaşır', 'Kaçış noktasında yeniden büyür'], 'Uzaklaşan nesneler küçük görünür, eşit aralıklar da giderek sıkışır. Bu kısalma, Rönesans resminde derinlik yanılsamasının temelidir.'),
  ('Bir portrede yalnızca kahverengimsi bir zemin önünde siyah giysili, beyaz kolalı yakalı bir tüccar gösterilir; fırça vuruşları hızlı ve görünürdür, adam bir şey söyleyecekmiş gibi gülümser. Bu portre en çok hangi geleneğe uyar?', '17. yüzyıl Hollanda portreciliği', ['15. yüzyıl Floransa profil portreciliği', '18. yüzyıl Fransız Rokoko saray portreciliği', 'Bizans ikona geleneği'], 'Sade siyah giysi ve beyaz yaka Hollanda burjuvazisinin modasıdır. Hızlı fırça ve anlık ifade, özellikle Frans Hals\'ın üslubunu hatırlatır.'),
  ('Raffaello\'nun ilk tablolarından bazılarının uzun süre hocası Perugino\'ya atfedilmiş olması neyi gösterir?', 'Çırakların ustanın üslubunu neredeyse kusursuzca benimsediğini', ['Perugino\'nun tablolarına başkasının adını yazdığını', 'Raffaello\'nun bilerek ustası adına sahte tablolar üretip sattığını', 'Rönesans\'ta imza atmanın yasak olduğunu'], 'Atölye eğitimi ustanın biçimlerini kopyalamaya dayanıyordu. Genç Raffaello, kendi üslubunu bulmadan önce Perugino\'nun yumuşak figürlerini ustaca taklit etmişti.'),
  ('Masaccio\'nun \'Kutsal Üçleme\' freskinin alt bölümünde bir lahit üzerinde yatan iskeletin üstünde \'Bir zamanlar sizin gibiydim, siz de benim gibi olacaksınız\' yazar. Bu bölüm izleyiciye ne hatırlatır?', 'Ölümün kaçınılmazlığını ve kurtuluş için inanca yönelmeyi', ['Bağışçının ne kadar zengin olduğunu', 'Freskin hangi yıl yapıldığını', 'Kilisenin eski bir mezarlığın üzerine kurulmuş olduğunu'], 'Bu tür \'memento mori\' yazıtları, izleyiciyi üstteki kutsal sahneye, yani kurtuluş umuduna yönlendirir. Fresk böylece aşağıdan yukarıya ölümden sonsuz yaşama doğru okunur.'),
  ('Fra Angelico\'nun Floransa\'daki San Marco Manastırı\'nın keşiş hücrelerine yaptığı sade, az figürlü fresklerin başlıca işlevi neydi?', 'Keşişlerin dua ve tefekkürüne yardımcı olmak', ['Manastırı ziyaret eden halka İncil\'i öğretmek', 'Medici ailesinin zenginliğini sergilemek', 'Hücrelerin numaralarını belirtmek'], 'Her hücrede İsa\'nın yaşamından bir sahne bulunur. Dikkat dağıtıcı ayrıntıların azaltılması, resimlerin sessiz bir dua aracı olmasını amaçlar.'),
  ('17. yüzyıl Hollanda sivil muhafız grup portrelerinde figürlerin çoğunun yüzü eşit görünürlükte ve yan yana dizilerek gösterilirdi. Bunun başlıca nedeni neydi?', 'Her üyenin tablodaki yeri için ücret ödemesi', ['Kent yasalarının hiyerarşik sırayı zorunlu kılması', 'Ressamların perspektif bilmemesi', 'Tabloların önce fotoğraf gibi çekilip sonra boyanması'], 'Ücret ödeyen her üye tanınır biçimde görünmek isterdi. Rembrandt\'ın \'Gece Devriyesi\' gibi hareketli düzenlemeler bu nedenle risk taşıyordu.'),
  ('El Greco\'nun gövdeleri uzatılmış, alev gibi yukarı doğru kıvrılan figürleri ve titreşen ışıkları en çok neyi ifade eder?', 'Maddeden kurtulup göğe yükselen manevi bir coşkuyu', ['Toledo halkının gerçek fiziksel özelliklerini', 'Ressamın görme bozukluğu nedeniyle gördüğü biçimleri', 'Antik Yunan heykellerinin kusursuz oranlarını'], 'El Greco Bizans ikonalarının ruhani geleneğini Venedik rengi ve maniyerist biçimle birleştirdi. Figürlerin uzaması dünyevi ağırlıktan kurtuluşun görsel karşılığıdır.'),
  ('Bruegel\'in \'Karnaval ile Perhiz\'in Savaşı\' tablosunda, fıçı üzerinde oturan şişman bir adam ile balık tutan sıska bir kadın karşı karşıya gelir. Bu karşılaşma neyi simgeler?', 'Paskalya öncesi eğlence dönemi ile oruç döneminin çatışmasını', ['Zenginlerle yoksullar arasındaki bir sokak kavgasını', 'Katoliklerle Müslümanlar arasındaki bir savaşı', 'Kış ile yaz mevsimlerinin her yıl birbirinin yerini almasını'], 'Karnaval, büyük perhiz başlamadan önceki bolluk ve eğlence günlerini temsil eder. Bruegel, kent meydanında iki dönemin geleneklerini kalabalık bir panorama içinde karşılaştırır.'),
  ('Fresk üzerinde çalışan bir ressam, günün sonunda sürdüğü sıvanın bir bölümünü boyayamadan kuruduğunu fark ediyor. Geleneksel yönteme göre ne yapmalıdır?', 'Boyanmamış kuru bölümü kazıyıp ertesi gün yeni sıva sürmelidir', ['Kuru bölümü vernikle kaplayıp bırakmalıdır', 'Kuru sıvanın üzerine aynı boyalarla hiçbir değişiklik yapmadan devam etmelidir', 'Duvarı tümüyle yıkıp yeniden örmelidir'], 'Yaş sıvaya bağlanmayan pigment kalıcı olmaz. Bu yüzden boyanmamış kenarlar kesilip atılır; yeni sıva bir sonraki günlük bölümle birleştirilir.'),
  ('Bir fresk ressamı bir günde yaklaşık 2 metrekare yüzey boyayabiliyor. 40 metrekarelik bir duvarı bitirmek için yaklaşık kaç günlük sıva bölümüne ihtiyaç duyar?', '20', ['10', '40', '80'], '40 / 2 = 20 günlük bölüm gerekir. Gerçekte bölümlerin boyu ayrıntıya göre değişir; yüzler küçük, gökyüzü geniş parçalarla boyanır.'),
  ('Bir Rönesans tablosunda zırhlı, genç bir şövalye atının üzerinden mızrağını bir ejderhanın ağzına saplar; arka planda bir prenses dua eder. Bu aziz kimdir?', 'Aziz Yorgi', ['Başmelek Mikail', 'Aziz Martinus', 'Aziz Mauritius'], 'Aziz Yorgi efsanesinde şövalye, kurban edilmek üzere olan prensesi ejderhadan kurtarır. Başmelek Mikail de ejderhayla dövüşür ama kanatlı bir melek olarak gösterilir.'),
  ('Kahverengi kaba bir keşiş giysisi giymiş, belinde düğümlü bir ip bulunan ve ellerinde ile ayaklarında İsa\'nınkine benzer yara izleri taşıyan bir aziz gösteriliyor. Bu aziz kimdir?', 'Assisili Aziz Franciscus', ['Aziz Dominikus', 'Aziz Benedictus', 'Aziz Antonius'], 'Franciscus\'un bedeninde İsa\'nın yaralarının belirdiğine (stigmata) inanılır. Düğümlü ip, tarikatın yoksulluk, iffet ve itaat yeminlerini simgeler.'),
  ('Bir eserde taçlı üç adam, ahırda annesinin kucağındaki bebeğin önünde diz çöküp altın, günnük ve mür armağan eder. Bu sahne hangi konudur?', 'Müneccimlerin Tapınması', ['Çobanların Tapınması', 'Tapınakta Takdim', 'Mısır\'a Kaçış'], 'İncil\'deki Doğulu bilginler Rönesans\'ta genellikle üç kral olarak gösterilir. Çobanların tapınmasında ise armağan getirenler kırsal kıyafetli yoksul çobanlardır.'),
  ('Bir eserde kanatlı bir melek elinde beyaz bir zambakla diz çöker; karşısında bir okuma pultunun başında oturan genç bir kadın şaşkınlıkla başını eğer. Bu sahne hangi konudur?', 'Müjde', ['Ziyaret', 'Meryem\'in Göğe Yükselişi', 'Meryem\'in Taç Giymesi'], 'Başmelek Cebrail, Meryem\'e Tanrı\'nın oğlunu doğuracağını haber verir. Kitap, Meryem\'in dindarlığını ve kehanetin gerçekleşmesini simgeler.'),
  ('Bir eserde Meryem kucağında bebekle bir eşeğin üzerinde oturur; Yusuf eşeği yederek ağaçlık bir yolda ilerler. Bu sahne hangi konudur?', 'Mısır\'a Kaçış', ['Beytüllahim\'e Yolculuk', 'Kudüs\'e Giriş', 'Tapınakta Takdim'], 'Kral Hirodes\'in bebekleri öldürteceğini öğrenen Yusuf, ailesini Mısır\'a götürür. Konu çoğu zaman geniş manzaralarla birlikte işlenmiştir.'),
  ('Bir Barok tablosunda askerler annelerin kucağından bebekleri koparıp kılıçla öldürür, kadınlar çığlık atarak karşı koyar. Bu sahne hangi İncil olayını gösterir?', 'Masumların Katliamı', ['Sabin Kadınlarının Kaçırılışı', 'Sodom\'un Yıkımı', 'Kudüs\'ün Yağmalanması'], 'Kral Hirodes, Mesih\'in doğduğunu duyunca Beytüllahim\'deki erkek bebeklerin öldürülmesini emreder. Rubens ve Guido Reni konuyu dramatik biçimde işlemiştir.'),
  ('Caravaggio\'nun bir eserinde bir havari, dirilen İsa\'nın göğsündeki yaraya parmağını sokarak yaranın gerçek olup olmadığını yoklar. Bu sahne hangi konudur?', 'Şüpheci Tomas', ['Saul\'un Dönüşümü', 'Emmaus\'ta Akşam Yemeği', 'Petrus\'un İnkârı'], 'Tomas, İsa\'nın dirildiğine yaraları görmeden inanmayacağını söylemişti. Caravaggio bu anı yakın plan ve kaba bir gerçekçilikle verir.'),
  ('Bir eserde genç bir kadın gümüş bir tepsi üzerinde kesilmiş bir erkek başı taşır. Bu figür büyük olasılıkla kimdir?', 'Salome', ['Yudit', 'Meryem', 'Ester'], 'Salome, dansının ödülü olarak Vaftizci Yahya\'nın başını ister ve baş ona tepsi içinde getirilir. Yudit ise Holofernes\'in başını kendisi keser ve genellikle kılıçla gösterilir.'),
  ('Bir eserde çıplak genç bir kadın deniz kıyısındaki bir kayaya zincirlenmiştir; kanatlı sandaletli bir kahraman, sudan çıkan bir canavara saldırır. Kadın kimdir?', 'Andromeda', ['Danae', 'Ariadne', 'Psykhe'], 'Perseus, deniz canavarına kurban edilmek istenen Etiyopya prensesi Andromeda\'yı kurtarır. Tiziano ve Rubens bu konuyu resmetmiştir.'),
  ('Bir eserde beyaz bir boğanın sırtına oturmuş bir kadın, korkuyla boğanın boynuzuna tutunurken boğa denize açılır. Bu sahne hangi mitolojiyi gösterir?', 'Europa\'nın Kaçırılışı', ['Leda ile Kuğu', 'Danae ile Altın Yağmur', 'Pasiphae\'nin Aşkı'], 'Zeus, Fenikeli prenses Europa\'yı kaçırmak için beyaz bir boğa kılığına girer. Tiziano\'nun II. Felipe için yaptığı tablo konunun en ünlü örneğidir.'),
  ('Caravaggio\'ya atfedilen bir eserde genç bir adam diz çökmüş, karanlık bir su birikintisindeki kendi yansımasına hayranlıkla eğilir. Bu figür kimdir?', 'Narkissos', ['Adonis', 'Endymion', 'Hyakinthos'], 'Narkissos kendi yansımasına âşık olup suyun başında eriyip gider. Tablo, figür ile yansımanın kapalı bir halka oluşturduğu kompozisyonuyla dikkat çeker.'),
  ('Rönesans ve Barok alegorilerinde gözleri bağlı, bir elinde terazi, öbüründe kılıç tutan kadın figürü hangi kavramı kişileştirir?', 'Adalet', ['Bilgelik', 'Talih', 'Barış'], 'Terazi tarafsız ölçümü, kılıç yaptırım gücünü, bağlı gözler ise kimseyi kayırmamayı simgeler. Göz bağı özellikle 16. yüzyıldan sonra yaygınlaştı.'),
  ('Bir müzayede kataloğunda bir tablonun altında \'Rembrandt atölyesi\' yazılıdır. Bu ifade ne anlama gelir?', 'Tablonun Rembrandt\'ın gözetiminde yardımcıları tarafından yapıldığı', ['Tablonun tümüyle Rembrandt\'ın kendi eliyle yapıldığı', 'Tablonun Rembrandt\'ın evinde asılı durduğu', 'Tablonun 19. yüzyılda bilinçli olarak yapılmış bir sahte olduğu'], 'Atölye ifadesi, eserin ustanın çevresinde ve denetiminde, ama büyük ölçüde başkalarının eliyle üretildiğini anlatır. \'Takipçisi\' ya da \'üslubunda\' ifadeleri ise daha uzak bir ilişkiyi gösterir.'),
  ('Pieter Brueghel (Genç), babasının \'Kardaki Avcılar\' ve \'Flaman Atasözleri\' gibi kompozisyonlarının birçok kopyasını üretmiştir. Bunun en olası nedeni nedir?', 'Babasının ünlü kompozisyonlarına yönelik piyasa talebi', ['Babasının vasiyetinde oğullarına bunu açıkça zorunlu kılması', 'Özgün tabloların tümünün yangında yok olmuş olması', 'Loncanın yeni konular resmetmeyi yasaklaması'], 'Yaşlı Bruegel\'in özgün tabloları az sayıdaydı ve büyük koleksiyonlara girmişti. Oğlunun atölyesi bu ünlü imgeleri daha geniş bir alıcı kitlesine ulaştırdı.'),
  ('Tiziano ve Rubens\'in resmettiği bir sahnede çıplak bir tanrıça, köpekleriyle ava çıkmak üzere olan genç bir avcıya sarılıp onu durdurmaya çalışır. Bu çift kimdir?', 'Venüs ve Adonis', ['Diana ve Endymion', 'Psykhe ve Eros', 'Echo ve Narkissos'], 'Venüs, avda öleceğini sezdiği sevgilisini alıkoymaya çalışır; Adonis bir yaban domuzu tarafından öldürülecektir. Tiziano\'nun düzenlemesi çok sayıda kopyayla yayılmıştır.'),
  ('Bir Rönesans tablosunda genç bir müzisyen lirini çalarken çevresindeki aslanlar, geyikler ve kuşlar sessizce onu dinler. Bu figür kimdir?', 'Orpheus', ['Pan', 'Apollon Musagetes', 'Hermes'], 'Orpheus\'un müziği vahşi hayvanları bile evcilleştirirdi. Konu Hristiyan sanatında İsa\'nın iyi çoban imgesiyle de ilişkilendirilmiştir.'),
  ('Rönesans ve Barok alegorilerinde yanında bir gemi çapası bulunan, gözlerini göğe kaldırmış kadın figürü hangi erdemi kişileştirir?', 'Umut', ['İnanç', 'Adalet', 'Ölçülülük'], 'Çapa, Pavlus\'un mektuplarında umudu ruhun güvenli demiri olarak anlatan sözlere dayanır. İnanç ise genellikle haç ya da kadehle gösterilir.'),
  ('Bir Barok heykel grubunda kucağında ve çevresinde birkaç bebeği emziren ve besleyen bir kadın figürü yer alır. Bu figür hangi erdemi temsil eder?', 'Hayırseverlik (Caritas)', ['Annelik', 'Bereket ve bolluk (Abundantia)', 'Sabır'], 'Caritas, Hristiyan erdemlerinin en yücesi sayılan sevgi ve yardımseverliktir. Çocukları besleyen anne imgesi bu fedakâr sevgiyi somutlaştırır.'),
  ('Bir Barok alegorisinde kanatlı, ak sakallı yaşlı bir adam elinde tırpan ve kum saati tutar; Bernini de bu figürü \'Zamanın Açığa Çıkardığı Hakikat\' için tasarlamıştı. Bu figür neyi kişileştirir?', 'Zaman', ['Ölüm', 'Kader ve yazgı', 'Kış'], 'Tırpan ve kum saati her şeyi biçen ve tüketen zamanı simgeler. Zamanın hakikati sonunda ortaya çıkardığı düşüncesi Barok alegorilerinde sık işlenmiştir.'),
  ('Bir Barok tavan resminde kanatlı bir kadın figürü uzun bir boru çalarak bir hükümdarın adını dünyaya duyurur. Bu figür hangi kavramın kişileştirmesidir?', 'Şöhret', ['Barış', 'Zafer', 'Bolluk'], 'Fama (Şöhret) genellikle bir ya da iki borazanla gösterilir. Hükümdarları yücelten saray tavanlarında sık rastlanan bir figürdür.'),
  ('Rönesans bronz heykellerinde kullanılan \'kayıp mum\' yönteminde balmumundan yapılan model sonunda ne olur?', 'Kalıp ısıtılınca eriyip akar ve yerini bronza bırakır', ['Heykelin dış yüzeyine cila olarak sürülür', 'Bronzun içinde kalıp heykelin kalıcı iç iskeleti olur', 'Kalıptan çıkarılıp yeniden kullanılmak üzere saklanır'], 'Mum eriyip boşalınca kalıpta heykelin biçiminde bir boşluk kalır ve eriyik bronz buraya dökülür. Mum model \'kaybolduğu\' için yöntem bu adı alır.'),
  ('Barok sanatçılarının bir öykünün başını ya da sonunu değil, en gergin ve doruk anını seçme eğiliminin başlıca amacı nedir?', 'İzleyiciyi olayın tam ortasında yakalayıp duygusal olarak sarsmak', ['Kompozisyonu olabildiğince sakin ve dengeli tutmak', 'Öykünün bütün aşamalarını tek resimde ayrıntılı anlatmak', 'Konuyu yalnız eğitimli seçkinlerin anlayabileceği bir bilmeceye çevirmek'], 'Bernini\'nin sapanını fırlatmak üzere olan Davut\'u ya da Caravaggio\'nun ani dönüşüm sahneleri, Barok\'un anlık ve dramatik etkiyi arayışını gösterir.'),
  ('Bir heykel, sakin bir duruşla ayakta duran, hafifçe ağırlığını tek bacağa vermiş, kendi içine kapanık ve önden izlenmek üzere bir niş için yapılmış bir aziz figürüdür. Bu heykel büyük olasılıkla hangi döneme aittir?', 'Erken Rönesans', ['Rokoko', 'Geç Barok', 'Maniyerizm'], 'Orsanmichele nişleri gibi önden izlenen yerler ve ölçülü kontrapost erken 15. yüzyıl heykelinin özellikleridir. Barok ve maniyerist heykeller ise hareketli ve çok yönlü izlemeye açıktır.'),
  ('Bir tavan resminde sınırsız bir gök açılır; aşağıdan bakıldığında kısaltılmış figürler, bulutlar ve melekler yükselir, alçı figürler boyalı alanla iç içe geçer. Bu tavan en çok hangi döneme aittir?', 'Barok', ['Erken Rönesans', 'Uluslararası Gotik', 'Romanesk'], 'Resim, heykel ve mimarinin birleşerek göğü yapının içine taşıdığı bu tavanlar 17. yüzyıl Roma\'sının tipik ürünüdür.'),
  ('Leonardo\'nun ve Michelangelo\'nun not defterlerindeki yüzlerce anatomik kesit çiziminin yapılabilmesi için ne gerekmiştir?', 'Kadavralar üzerinde inceleme yapma izni ve olanağı', ['Antik Yunan\'dan kalan hazır anatomi atlaslarının bulunması', 'Hastanelerde röntgen cihazlarının kullanılması', 'Yalnızca hayvanların gözlemlenmesi'], 'Leonardo, Floransa\'daki Santa Maria Nuova hastanesinde ve sonra Milano ile Roma\'da kadavra inceledi. Bu çalışmalar onun resimlerindeki gerçekçi beden bilgisinin temelidir.'),
  ('Bir küratör Vermeer ile Pieter de Hooch\'un tablolarını aynı salonda sergilemek istiyor. Aşağıdakilerden hangisi bu seçim için en uygun gerekçedir?', 'İkisinin aynı kentte, aynı yıllarda benzer ev içi konuları işlemesi', ['İkisinin de dev boyutlu kilise sunakları yapması', 'İkisinin de İtalya\'ya gidip Roma\'da Caravaggio\'nun öğrencisi olması', 'İkisinin de yalnızca deniz savaşları resmetmesi'], 'Her iki ressam da 1650\'lerde Delft\'te çalıştı; avlular, odalar ve kadınların gündelik işleri ortak konularıydı. Yan yana sergileme karşılıklı etkileşimi görünür kılar.'),
  ('Natürmort için Hollandacada kullanılan \'stilleven\' sözcüğü, türe adını veren hangi anlamı taşır?', 'Durgun, hareketsiz model', ['Masa süsü', 'Ölü doğa', 'Mutfak resmi'], '\'Stil\' durgun, \'leven\' ise model ya da yaşam demektir. Fransızcadaki \'nature morte\' (ölü doğa) adı ise sonradan yaygınlaşmıştır.'),
  ('Bosch\'un \'Dünyevi Zevkler Bahçesi\' triptiğinin üç panosu soldan sağa genellikle nasıl yorumlanır?', 'Cennet, dünyevi zevkler ve cehennem', ['Sabah, öğle ve akşam', 'Doğum, evlilik ve ölüm aşamaları', 'Bahar, yaz ve kış'], 'Sol pano Âdem ile Havva\'nın yaratılışını, orta pano çıplak insanların zevk dünyasını, sağ pano ise korkunç bir cehennemi gösterir. Okuma günahtan cezaya giden bir ahlaki yol çizer.'),
  ('Ghent Sunağı\'nın orta panosunda bir sunağın üzerinde duran ve göğsünden bir kadehe kan akan kuzu kimi simgeler?', 'İsa\'yı', ['Vaftizci Yahya\'yı', 'Havari Petrus\'u', 'Bağışçı Joos Vijd\'i'], '\'Tanrı\'nın Kuzusu\' İsa\'nın kurban edilişinin simgesidir. Dört yandan gelen azizler, peygamberler ve şehitler kuzuya tapınmaya yönelir.'),
  ('Frans Hals\'ın portrelerinde fırça vuruşlarını karıştırıp düzleştirmeden, hızlı ve görünür bırakması nasıl bir etki yaratır?', 'Anlık ve canlı bir hareket ve ifade izlenimi', ['Yüzeyin cam gibi pürüzsüz görünmesi', 'Donmuş, heykel gibi kımıltısız bir sessizlik ve resmiyet', 'Figürün altın zemin üzerinde düz kalması'], 'Hals\'ın fırçası gülüşü ya da bir bakışı tam o anda yakalamış gibi görünür. Bu teknik, Leiden\'in pürüzsüz \'ince ressamlar\' anlayışının tam karşıtıdır.'),
  ('17. yüzyıl Hollanda manzara resimlerinde ufuk çizgisinin çoğu zaman çok alçak tutulup tuvalin büyük bölümünün gökyüzüne ayrılmasının başlıca nedeni nedir?', 'Düz ülkede değişken bulutlu göğün manzaranın asıl dramını oluşturması', ['Tuvalin üst kısmının boya tasarrufu için boş bırakılması', 'Kiliselerin manzara resmini dinsel bir konu sayıp yalnızca gökyüzünü göstermeyi zorunlu tutması', 'Alıcıların tabloları tavana asmayı tercih etmesi'], 'Hollanda\'nın düz ovalarında dağ ya da tepe yoktur. Ruisdael ve van Goyen gibi ressamlar ışığı ve hareketi gökyüzündeki bulutlar aracılığıyla verdi.'),
  ('17. yüzyıl Hollanda Cumhuriyeti\'nde gemi ve deniz savaşı tablolarının çok sevilmesi en iyi nasıl açıklanır?', 'Ticaret ve donanma gücüyle övünen bir toplumun kimliğini yansıtması', ['Kilisenin deniz konularını dinsel sayıp desteklemesi', 'Hollanda\'da kara manzarası resmetmenin uzun süre yasalarla yasaklanmış olması', 'Ressamların çoğunun gemici olarak çalışması'], 'Hollanda\'nın zenginliği denizaşırı ticarete ve güçlü bir donanmaya dayanıyordu. Deniz resimleri bu ulusal başarıyı ve denizle iç içe yaşamı kutluyordu.'),
  ('Vitruvius\'a göre çeneden saç diplerine kadar yüz uzunluğu, insan boyunun onda biridir. Rönesans ressamlarının izlediği bu orana göre 180 cm boyundaki bir figürün yüz uzunluğu kaç cm olmalıdır?', '18 cm', ['12 cm', '24 cm', '30 cm'], '180 / 10 = 18 cm. Leonardo\'nun ünlü Vitruvius Adamı çizimindeki notlar da bu oran kurallarını aktarır.'),
  ('Botticelli ve Ghirlandaio gibi Rönesans ressamlarının kalabalık dinsel sahnelerin kenarına kendi yüzlerini yerleştirip izleyiciye baktırmasının en olası nedeni nedir?', 'Bir tür imza olarak kendilerini tanıtıp yükselen saygınlıklarını göstermek', ['Model ücreti ödememek için kendilerini kullanmaları', 'Kilisenin her eserde ressamın yüzünün yer almasını sözleşmelerde zorunlu tutması', 'Sahnedeki aziz olarak tapınılmak istemeleri'], 'Sanatçının statüsü yükseldikçe kendini eserin içinde göstermek, ustalığını ve kişiliğini kayda geçirmenin bir yolu oldu. Bakış, izleyiciyi sahneye davet eder.'),
  ('Bir sunak resminde İsa\'nın kefene sarılmış bedeni, birkaç kişi tarafından kayaya oyulmuş bir lahdin içine indirilmektedir. Bu sahne hangi konudur?', 'Gömülme', ['Çarmıhtan İndiriliş', 'Diriliş', 'Lazarus\'un Dirilişi'], 'Gömülme (Entombment) sahnesi, ağıttan sonraki aşamadır. Raffaello ve Caravaggio bu konuyu güçlü kompozisyonlarla işlemiştir.'),
  ('Bir eserde Meryem bulutların ve meleklerin arasında göğe doğru yükselir; aşağıda havariler boş bir mezarın başında şaşkınlıkla yukarı bakar. Bu sahne hangi konudur?', 'Meryem\'in Göğe Yükselişi', ['İsa\'nın Göğe Yükselişi', 'Meryem\'in Ölümü', 'Kutsal Ruh\'un İnişi'], 'Katolik inancına göre Meryem ölümünden sonra bedeniyle göğe alınmıştır. Boş mezar ve havariler bu sahnenin tipik öğeleridir.'),
  ('Bir eserde gökte tahtta oturan İsa, yanında diz çökmüş Meryem\'in başına bir taç koyar; çevrede melekler ve azizler toplanmıştır. Bu sahne hangi konudur?', 'Meryem\'in Taç Giymesi', ['Meryem\'in Evlenmesi', 'Müjde', 'Meryem\'in Takdimi'], 'Meryem\'in Gökler Kraliçesi olarak taç giymesi, özellikle Orta Çağ sonu ve Rönesans sunaklarında yaygın bir konuydu.'),
  ('Bir Rönesans tablosunda kanatlı başlık ve kanatlı sandaletler giymiş, elinde yılan dolanmış bir asa tutan genç tanrı kimdir?', 'Merkür (Hermes)', ['Mars (Ares)', 'Apollon', 'Vulcanus (Hephaistos)'], 'Merkür tanrıların habercisidir; yılanlı asası \'caduceus\' adını taşır. Botticelli\'nin \'Primavera\'sında sol kenardaki figür de odur.'),
  ('Rubens\'in bir tablosunda güçlü bir adam bir kadının kucağında uyurken bir başka adam onun saçlarını keser; kapıda askerler beklemektedir. Bu sahne hangi öyküdür?', 'Samson ile Delila', ['Davut ile Bathşeba', 'Yusuf ile Potifar\'ın karısı', 'Holofernes ile Yudit'], 'Samson\'un gücü saçlarındaydı; Delila onu Filistinlilere ele verir. Rubens\'in tablosu Londra\'daki Ulusal Galeri\'dedir.'),
  ('Raffaello\'nun Bolonya\'daki bir sunağında, elinde küçük bir org tutan ve gökteki melek korosunu dinleyen genç bir azize gösterilir. Bu azize kimdir?', 'Azize Cecilia', ['Azize Lucia', 'Azize Agatha', 'Azize Apollonia'], 'Cecilia, müziğin ve müzisyenlerin koruyucu azizesidir. Raffaello\'nun tablosunda ayaklarının dibinde kırık çalgılar dünyevi müziğin göksel müzik karşısındaki değersizliğini anlatır.'),
  ('Rönesans resimlerinde yanında üç pencereli küçük bir kule taşıyan ya da bir kulenin önünde duran azize kimdir?', 'Azize Barbara', ['Azize Katerina', 'Azize Ursula', 'Azize Margareta'], 'Efsaneye göre babası Barbara\'yı bir kuleye kapatmıştır; üç pencere onun inandığı Kutsal Üçleme\'yi simgeler. Topçuların ve madencilerin koruyucusu sayılır.'),
  ('Rönesans resimlerinde azizlerin her zaman kendilerine özgü nesnelerle (tekerlek, ok, anahtar gibi) gösterilmesinin başlıca işlevi neydi?', 'İzleyicinin azizi kolayca tanıyabilmesini sağlamak', ['Ressamın kendi zevkine göre süsleme yapmasını sağlamak', 'Azizlerin mesleklerini belgelemek', 'Resmin değerini artıran pahalı ayrıntılar eklemek'], 'Okuma yazma bilmeyenlerin de çoğunlukta olduğu bir toplumda bu ayırt edici nesneler, azizin öyküsünü bir bakışta hatırlatan görsel bir dildi.'),
  ('15. yüzyıl İtalyan sunak sözleşmelerinde sık görülen \'ressam yüzleri kendi eliyle boyayacaktır\' maddesi neyi amaçlar?', 'En önemli bölümlerin yardımcılara bırakılmamasını güvenceye almak', ['Ressamın yüz boyamayı öğrenmesini zorunlu kılmak', 'Yüzlerin bağışçıya benzetilmesini yasaklamak', 'Resmin yalnız tek renkle yapılmasını sağlamak'], 'Atölyelerde arka plan ve giysiler çoğunlukla yardımcılarca boyanırdı. Patronlar, ustalığın en çok görüldüğü yüzlerin bizzat ustanın elinden çıkmasını isterdi.'),
  ('Aşağıdaki sanatçılardan hangisi Barok dönemin sanatçısı değildir?', 'Sandro Botticelli', ['Peter Paul Rubens', 'Gian Lorenzo Bernini', 'Diego Velázquez'], 'Botticelli 15. yüzyıl Floransa\'sının, yani Erken Rönesans\'ın ressamıdır. Rubens, Bernini ve Velázquez ise 17. yüzyıl Barok sanatının önde gelen ustalarıdır.'),
  ('Aşağıdaki ressamlardan hangisi Erken Hollanda (Flaman primitifleri) geleneğine ait değildir?', 'Piero della Francesca', ['Jan van Eyck', 'Rogier van der Weyden', 'Hans Memling'], 'Piero della Francesca, 15. yüzyılda Umbria ve Toskana\'da çalışan bir İtalyan ressamdır. Diğer üçü Brugge, Brüksel ve Ghent çevresinde çalışan Flaman ustalardır.'),
  ('Aşağıdaki ressamlardan hangisi Venedik okulundan değildir?', 'Masaccio', ['Giorgione', 'Tintoretto', 'Paolo Veronese'], 'Masaccio Floransalı bir Erken Rönesans ressamıdır. Giorgione, Tintoretto ve Veronese ise 16. yüzyıl Venedik resminin temsilcileridir.'),
  ('Aşağıdaki sanatçı ve çalıştığı başlıca kent eşleştirmelerinden hangisi yanlıştır?', 'Pieter Bruegel (Yaşlı) – Madrid', ['Gian Lorenzo Bernini – Roma', 'Peter Paul Rubens – Anvers', 'Rembrandt van Rijn – Amsterdam'], 'Yaşlı Bruegel Anvers ve Brüksel\'de çalışmıştır. Bosch tablolarının çoğu sonradan Madrid\'e gitmiş olsa da Bruegel\'in orada çalıştığı bir dönem yoktur.'),
  ('Aşağıdaki eserlerden hangisi 17. yüzyılda yapılmıştır?', 'Velázquez\'in Nedimeler\'i', ['Leonardo\'nun Mona Lisa\'sı', 'Botticelli\'nin Primavera\'sı', 'Tiepolo\'nun Würzburg freski'], 'Nedimeler 1656\'da yapılmıştır. Primavera 15., Mona Lisa 16. yüzyılın başına, Würzburg freski ise 18. yüzyılın ortasına aittir.'),
  ('18. yüzyılda pastel portrelerin özellikle sevilmesinin nedenlerinden biri hangisidir?', 'Kuruma beklemeden hızlı çalışılabilmesi ve tenin yumuşak görünmesi', ['Pastelin yağlı boyadan çok daha dayanıklı olması', 'Pastel tabloların kolayca yıkanabilmesi', 'Pastelin yalnızca kiliselerde kullanılmasına izin verilmesi'], 'Kuru pastel, poz verme sürelerini kısaltır; tozlu, kadifemsi yüzeyi de pudralı Rokoko yüzlerine çok uygundur. Ancak kolay bozulduğu için camla korunması gerekir.'),
  ('Rembrandt\'ın bakır gravür yerine asitle oymayı (etching) yeğlemesinin başlıca nedeni nedir?', 'Çizginin kalemle çizer gibi serbest ve akıcı olabilmesi', ['Baskıların renkli çıkması', 'Kalıbın hiç aşınmaması', 'Asidin kâğıdı daha beyaz yapması'], 'Asitle oymada sanatçı yumuşak vernik üzerine iğneyle rahatça çizer. Burinle metali doğrudan oymak ise güç ve zanaat gerektirir.'),
  ('Dürer hem ağaç baskı hem bakır gravür yapmıştır. Bakır gravürün ağaç baskıya göre başlıca üstünlüğü nedir?', 'Çok daha ince çizgi ve ton geçişlerine olanak vermesi', ['Kalıbın çok daha ucuza ve hızla hazırlanması', 'Baskının kabartma yöntemiyle alınması', 'Kitap sayfalarıyla aynı baskı makinesinde basılabilmesi'], 'Metal levhadaki ince oyuklar, ağaçta oyulması zor olan çok ince tarama ve ayrıntılara izin verir. Ağaç baskı ise metinle birlikte basılabildiği için kitaplarda daha pratikti.'),
  ('Bir portredeki modelin boynunda geniş, kat kat kolalanmış ve değirmen taşını andıran beyaz bir yaka bulunuyor. Bu portre büyük olasılıkla hangi döneme aittir?', '16. yüzyıl sonu ile 17. yüzyıl başı', ['13. yüzyıl başı', '15. yüzyıl başı', '18. yüzyıl sonu'], 'Bu tür yakalar 1560\'lardan 1630\'lara kadar Avrupa\'da, özellikle İspanya ve Hollanda\'da çok yaygındı. Giysi ayrıntıları portrelerin tarihlendirilmesinde önemli ipuçlarıdır.'),
  ('Floransa\'da bir şapelin sunak resminde, altın bir kalkan üzerinde kırmızı toplardan oluşan bir arma görülüyor. Bu eserin hamisi büyük olasılıkla hangi ailedir?', 'Medici', ['Sforza', 'Gonzaga', 'Este'], 'Medicilerin arması altın zemin üzerinde kırmızı toplardır (palle). Aile, ısmarladığı eserlere armasını koydurarak cömertliğini ve gücünü görünür kılardı.'),
  ('Vermeer ve çağdaşlarının ev içi sahnelerinde duvarda asılı büyük haritaların sık görülmesi neyi yansıtır?', 'Hollanda\'nın haritacılık ve küresel ticaretteki öncülüğünü', ['Evin sahibinin askerî bir komutan olduğunu', 'Haritaların duvar kâğıdı yerine kullanılmasını', 'Kilisenin coğrafya öğretimini zorunlu kılmasını'], 'Amsterdam 17. yüzyılda Avrupa\'nın harita yayıncılığı merkeziydi. Haritalar hem değerli bir süs eşyası hem de dünyaya açılan bir ticaret ulusunun gururuydu.'),
  ('Bir Rönesans tablosunda ressamın adının yanında Latince \'pinxit\' sözcüğü yer alıyorsa bu ne anlama gelir?', '\'Boyadı\'', ['\'Bağışladı\'', '\'Satın aldı\'', '\'Onardı\''], 'Ressamlar imzalarında \'pinxit\' (boyadı) ya da \'fecit\' (yaptı) gibi Latince fiiller kullanırdı. Heykeltıraşlar için \'sculpsit\' tercih edilirdi.'),
  ('Bir tablonun köşesinde Roma rakamlarıyla \'MDCXLII\' tarihi yazılıdır. Bu tarih hangi yılı gösterir?', '1642', ['1462', '1662', '1592'], 'M = 1000, DC = 600, XL = 40, II = 2; toplam 1642. Bu, Rembrandt\'ın \'Gece Devriyesi\'ni tamamladığı yıldır.'),
  ('Jan van Eyck\'in \'Arnolfini Portresi\'nde, arka duvardaki aynanın üstüne süslü harflerle \'Johannes de eyck fuit hic 1434\' yazılmıştır. Bu yazı ne anlama gelir?', 'Jan van Eyck buradaydı, 1434', ['Jan van Eyck bunu yaptı, 1434', 'Jan van Eyck burada evlendi, 1434', 'Jan van Eyck bunu sattı, 1434'], 'Ressam \'yaptı\' yerine \'buradaydı\' diyerek kendisini sahnenin bir tanığı gibi sunar. Bu ifade, tablonun bir tür belge niteliği taşıdığı yorumlarına yol açmıştır.'),
  ('\'Büyük Tur\'a çıkan genç İngiliz soylularının Canaletto\'nun Venedik manzaralarını satın almasının başlıca işlevi neydi?', 'Yolculuğun hatırası olarak evlerine götürmek', ['Venedik\'te arazi satın almak için belge sunmak', 'Okulda mimarlık dersinde kullanmak', 'Venedik hükümetine vergi ödemek'], 'Grand Tour, eğitimin tamamlanması sayılan uzun bir Avrupa yolculuğuydu. Kent manzaraları, fotoğrafın olmadığı bir çağda gezinin görsel hatırası işlevi gördü.'),
  ('17. yüzyıl Hollanda ev içi tablolarında süpürge, kova ve parlatılmış yer döşemeleri gibi temizlik ayrıntılarının özenle gösterilmesi neyi yansıtır?', 'Evin düzenine ve temizliğine yüklenen ahlaki değeri', ['Ressamların temizlik malzemesi satan dükkânlar işletmesini', 'Hollanda\'da sık görülen sel felaketlerini', 'Evlerin yalnızca hizmetçiler tarafından kullanılmasını'], 'Temiz ve düzenli ev, Kalvinist toplumda erdemli bir yaşamın göstergesi sayılıyordu. Pieter de Hooch ve Vermeer\'in sakin iç mekânları bu değeri yüceltir.'),
  ('El Greco\'nun \'Kont Orgaz\'ın Gömülmesi\' tablosunun alt bölümünde cenazeye katılan siyah giysili soylu kalabalığın yüzleri kime aittir?', 'Dönemin Toledo seçkinlerinin portrelerine', ['Antik Roma imparatorlarının büstlerine', 'Ressamın hayalinde yarattığı tiplere', 'İspanya krallarının soy ağacına'], 'El Greco, sahneyi yüzyıllar önce yaşanmış bir mucize olmasına karşın kendi döneminin Toledo\'lu soylularıyla doldurdu. Ön plandaki çocuğun ressamın oğlu olduğu da kabul edilir.'),
  ('17. yüzyıl İspanya\'sında çıplak kadın tablolarının çok az yapılmış olmasının başlıca nedeni nedir?', 'Engizisyonun ve kilisenin çıplaklık üzerindeki sıkı denetimi', ['İspanyol ressamların anatomi bilmemesi', 'Tuval ve boya ithalatının yasaklanması', 'Kraliyet sarayının yalnızca manzara resmi istemesi'], 'Çıplaklık dinsel ve ahlaki açıdan sakıncalı sayılıyordu. Bu nedenle Velázquez\'in \'Aynadaki Venüs\'ü İspanyol resminde ender bir örnektir.'),
  ('Bir müze etiketinde \'tuval üzerine yağlı boya, Anvers, 1640\'lar, kalabalık bir şölen sahnesi\' yazıyor. Aşağıdaki ressamlardan hangisi bu eserin yapımcısı olmaya en uygundur?', 'Jacob Jordaens', ['Sandro Botticelli', 'Giovanni Battista Tiepolo', 'Masaccio'], 'Jordaens, Rubens\'in 1640\'taki ölümünden sonra Anvers\'in önde gelen ressamı oldu ve şölen sahneleriyle tanındı. Diğer ressamlar farklı yüzyıllarda ve kentlerde çalışmıştır.'),
  ('Vatikan Sarayı\'nın odalarındaki 1509-1511 tarihli büyük duvar fresklerinden birinin ressamı aşağıdakilerden hangisi olabilir?', 'Raffaello', ['Rubens', 'Vermeer', 'Bruegel'], 'Raffaello, II. Julius\'un isteğiyle bu yıllarda Stanza della Segnatura\'yı boyadı. Diğer ressamlar ya başka yüzyıllarda yaşamış ya da fresk ustası değildir.'),
  ('Holbein\'in VIII. Henry\'yi tam cepheden, bacaklarını açmış, omuzları geniş ve elleri belinde gösterdiği portre tipi hangi amaca hizmet eder?', 'Kralın gücünü ve otoritesini heybetli biçimde yansıtmak', ['Kralın hastalıklı ve zayıf olduğunu göstermek', 'Kralı sıradan bir köylü gibi tanıtmak', 'Kralın ressama duyduğu öfkeyi belgelemek'], 'Whitehall Sarayı için yapılan büyük duvar resmindeki bu poz, kopyalarla yayılarak kralın resmî imgesine dönüştü. İzleyici, karşısında dimdik duran bir iktidar figürü bulur.'),
  ('Michelangelo\'nun Vatikan Pietà\'sında Meryem\'in bedeni, özellikle geniş giysi kıvrımlarıyla, İsa\'nınkinden belirgin biçimde iri yapılmıştır. Bunun başlıca nedeni nedir?', 'Yetişkin bir bedeni kucağında taşımasını inandırıcı kılmak', ['Meryem\'i İsa\'dan daha önemli göstermek', 'Mermerdeki bir çatlağı gizlemek', 'Heykeli yalnız arkadan bakılacak biçimde tasarlamak'], 'Gerçek oranlarda bir kadın yetişkin bir erkeği dizlerinde dengeli biçimde tutamazdı. Michelangelo, giysi kıvrımlarıyla piramit biçiminde geniş bir taban yaratarak bu sorunu çözdü.'),
  ('Bir müzede iki tablo yan yana asılıdır: birinde figürler net konturlarla çizilmiş, renkler ayrı alanlar hâlinde sürülmüştür; ötekinde biçimler ışık ve renk lekeleri içinde erir, fırça izleri görünür. Bu karşıtlık en iyi hangi iki geleneği yansıtır?', 'Floransa\'nın çizgi ile Venedik\'in renk geleneğini', ['Bizans\'ın ikona ile Gotik\'in vitray geleneğini', 'Mısır\'ın duvar resmi ile Roma\'nın mozaik geleneğini', 'Hollanda\'nın natürmort ile İspanya\'nın bodegón geleneğini'], 'Floransa\'da biçimi çizgi (disegno) kurarken Venedik\'te Tiziano gibi ustalar biçimi renk ve ışıkla (colorito) oluşturdu. Bu ayrım Rönesans sanat kuramının temel tartışmalarındandır.'),
  ('Rembrandt\'ın gençlikten yaşlılığa kadar kendini aynada birçok kez resmetmesinin pratik nedenlerinden biri hangisidir?', 'Her zaman hazır ve ücretsiz bir model olması', ['Kilisenin otoportreyi zorunlu tutması', 'Başka insanları resmetmenin yasak olması', 'Aynaların o dönemde çok ucuz olması'], 'Kendi yüzü, ressamın ifade, ışık ve kostüm denemeleri yapabileceği en kolay modeldi. Bu çalışmalar aynı zamanda piyasada satılabilen tronie\'ler olarak da işlev gördü.'),
  ('Erken Rönesans sunak resimlerinde arka plandaki altın zeminin yerini giderek mavi gökyüzü ve manzaranın alması hangi eğilimi gösterir?', 'Kutsal olayın görünen gerçek dünyada geçtiğini gösterme isteğini', ['Altının ressamlar için yasaklanmasını', 'Kilisenin resimleri daha ucuza ısmarlamak istemesini', 'Mavi boyanın altından daha değersiz sayılmasını'], 'Altın zemin kutsal olayı zamandan ve mekândan soyutlar. Manzara ise olayı izleyicinin tanıdığı bir doğa içine yerleştirerek ona yakınlaştırır.'),
];
